'use strict';
const REPORT_UI5={bind,help};
let reportKind5='stores',reportWeeks5=1,reportSort5='attention';
TITLES.performance='Report výkonu firmy';
function reportValue5(value,cfg){if(value===null||value===undefined)return '—';const unit=cfg[1];return unit==='money'?money(value):unit==='kg'?number(value,1)+' kg':unit==='score'?number(value,1)+' / 100':unit==='ratio'?number(value*100,1)+' %':unit==='percent'?number(value,1)+' %':unit==='min'?number(value,1)+' min':number(value,1);}
function reportSpark5(row,key){const points=row.points.filter(p=>p.values[key]!==null),values=points.map(p=>p.values[key]);if(values.length<2)return '<span class="sub">Čeká na další týden</span>';const min=Math.min(...values),max=Math.max(...values),range=max-min||1,coordinates=values.map((n,i)=>`${8+i/(values.length-1)*134},${40-(n-min)/range*32}`).join(' ');return `<svg class="report-spark5" viewBox="0 0 150 48" role="img" aria-label="Vývoj: ${esc(values.map(n=>number(n,1)).join(', '))}"><path d="M8 42H142" stroke="#ddd8c8"/><polyline points="${coordinates}" fill="none" stroke="#264b3b" stroke-width="2.5"/></svg>`;}
function reportTrend5(row){const primary=REPORT_GROUPS5[reportKind5].primary,cfg=REPORT_FIELDS5[reportKind5][primary];return row.trend===null?'<span class="sub">Bez srovnání</span>':`<strong>${row.trend>0?'+':''}${reportValue5(row.trend,cfg)}</strong><small>průměr / týden · proti ${row.previousCount} předchozím</small>`;}
function reportRowsSorted5(report){return [...report.rows].sort((a,b)=>reportSort5==='name'?a.name.localeCompare(b.name,'cs'):reportSort5==='attention'?b.severity-a.severity||a.name.localeCompare(b.name,'cs'):a.values[REPORT_GROUPS5[reportKind5].primary]===null?1:b.values[REPORT_GROUPS5[reportKind5].primary]===null?-1:(b.values[REPORT_GROUPS5[reportKind5].primary]-a.values[REPORT_GROUPS5[reportKind5].primary])*(reportSort5==='lowest'?-1:1));}
function performanceView(){const report=performanceReport5(reportKind5,reportWeeks5),fields=REPORT_FIELDS5[reportKind5],group=REPORT_GROUPS5[reportKind5],primary=fields[group.primary],secondary=fields[group.secondary],h=state.history.at(-1),period=state.history.filter(h=>h.week>=report.start&&h.week<=report.end),profit=period.reduce((s,h)=>s+h.profit,0),revenue=period.reduce((s,h)=>s+h.revenue,0);return `<div class="view-toolbar"><p class="intro">${h?'Uzavřené výsledky do týdne '+h.week+'.':'Odehraj první týden pro výsledky.'} Otevři řádek pro podrobnosti a návazné řízení.</p><div class="fields">${field('Období',`<select id="reportWeeks5">${[1,4,13].map(n=>option(n,n===1?'Poslední týden':n===4?'Poslední 4 týdny':'Čtvrtletí · 13 týdnů',reportWeeks5)).join('')}</select>`)}${field('Seřadit',`<select id="reportSort5">${option('attention','Nejdřív problémy',reportSort5)}${option('highest','Nejvyšší výsledek',reportSort5)}${option('lowest','Nejnižší výsledek',reportSort5)}${option('name','Podle názvu',reportSort5)}</select>`)}</div></div><div class="report-overview5">${metric('VÝSLEDEK FIRMY',period.length?money(profit):'—',period.length+' uzavřených týdnů',profit<0?'bad':'')}${metric('TRŽBY FIRMY',period.length?money(revenue):'—','Kavárny, obchod a e-shop')}${metric('HOTOVOST DNES',money(state.cash),'Dluh '+money(state.debt))}${metric('VYŽADUJE POZORNOST',report.rows.filter(r=>r.severity>0).length,group.name+' · poslední zaznamenaný stav')}</div><div class="report-tabs5" role="group" aria-label="Typ výsledků">${Object.entries(REPORT_GROUPS5).map(([k,g])=>`<button class="${k===reportKind5?'primary':'soft'}" data-report-kind="${k}" aria-pressed="${k===reportKind5}">${g.name}</button>`).join('')}</div><section class="card"><div class="card-head"><h2>${group.name}</h2><span class="badge">${report.rows.length} záznamů</span></div><p class="sub report-coverage5">${report.end?'Požadované období: týdny '+Math.max(1,report.start)+'–'+report.end+'. Podrobné záznamy: '+report.count+' z '+Math.min(report.weeks,report.end)+' týdnů.':'Zatím žádný uzavřený týden.'} Historie jednotlivých provozů se zaznamenává od této aktualizace; starší hra poskytne poslední dostupný týden. Čísla řádku zahrnují jen týdny s jeho vlastním záznamem.</p>${report.rows.length?`<div class="table-scroll"><table class="data performance-table5"><thead><tr><th scope="col">${reportKind5==='people'?'Osoba / role':'Název / působnost'}</th><th scope="col">${primary[0]}</th><th scope="col">${secondary[0]}</th><th scope="col">Vývoj</th><th scope="col">Stav a odpovědnost</th><th scope="col">Report</th></tr></thead><tbody>${reportRowsSorted5(report).map(r=>`<tr><td><strong>${esc(r.name)}</strong><small>${esc(r.points.at(-1)?.scope||r.scope)}${r.historical?' · historický záznam':''}</small></td><td class="${reportKind5==='stores'||reportKind5==='firms'?r.values[group.primary]<0?'bad':'':''}"><strong>${reportValue5(r.values[group.primary],primary)}</strong><small>${r.points.length} zaznamenaných týdnů</small></td><td>${reportValue5(r.values[group.secondary],secondary)}</td><td>${reportSpark5(r,group.primary)}${reportTrend5(r)}</td><td><span class="report-status5 ${r.severity===2?'bad':r.severity===1?'attention':''}">${esc(r.issue)}</span><small>${esc(r.owner)}</small></td><td><button class="soft mini" data-performance-detail="${r.id}">Otevřít detail</button></td></tr>`).join('')}</tbody></table></div>`:empty(reportKind5==='people'?'Ve firmě zatím nemáš najaté vedoucí.':reportKind5==='estates'?'Zatím nevlastníš žádnou plantáž.':'Pro tento přehled zatím nejsou provozy.')}</section><p class="sub report-footnote5">${reportKind5==='stores'?'Výsledek kavárny zahrnuje její provoz a spotřebovanou kávu. Centrála, výroba, doprava a finance jsou zahrnuté až ve výsledku celé firmy. Franšíza ukazuje příjem a výsledek tvé firmy.':reportKind5==='roasters'?'Pražírny mají výrobní výkon a provozní náklady. Zrna, zpracování šarží a servis se účtují odděleně; výroba nemá uměle přidělené prodejní tržby.':reportKind5==='estates'?'Výdaje pěstování se ukládají do nákladu budoucí sklizně; přeprava je součástí ceny zrn. Týden bez sklizně má nulovou sklizeň, nikoli nulovou práci.':reportKind5==='people'?'Výsledek svěřených kaváren poskytuje kontext práce vedoucího; ovlivňují jej také ceny, zásoby a investice. Není samostatným skóre jeho zásluh. Mzda je smluvní týdenní sazba v zaznamenané roli.':reportKind5==='departments'?'Mzdy zahrnují pracovníky oddělení a jeho ředitele. Náklady projektů, školení a dalších zásahů jsou v reportech vedení a účetnictví firmy.':reportKind5==='guests'?'Návštěvy mohou zahrnovat opakované příchody. Stálí hosté jsou aktivní zákaznický okruh; návraty jsou jeho obsloužené návštěvy. Veřejné hodnocení je průměr posledních 30 recenzí pobočky.':reportKind5==='trade'?'Příspěvek odběru zahrnuje spotřebovanou kávu, balení, dopravu a smluvní pokuty. Centrála, mzdy a jednání jsou ve výsledku firmy. Faktury se účtují při dodání; inkaso mění hotovost.':'Soupeři používají agregovaný provozní model. Jejich zisk a hotovost jsou skutečné výsledky simulace; samostatné tržby nejsou dostupné.'}</p>`;}
function performanceDetail5(id){const report=performanceReport5(reportKind5,reportWeeks5),r=report.rows.find(r=>r.id===id);if(!r)return;const fields=REPORT_FIELDS5[reportKind5],dest=reportKind5==='stores'?'stores':reportKind5==='roasters'?'roasters':reportKind5==='estates'?'estates':reportKind5==='people'?'people':reportKind5==='departments'?'hq':reportKind5==='trade'?'business':reportKind5==='guests'?'guests':id==='player'?'finance':'rivals';let extra='';if(reportKind5==='stores'){const s=state.stores.find(s=>s.id===id);if(s?.last)extra=`<h3>Náklady posledního týdne</h3>${rows(Object.entries(s.last.detail).map(([k,v])=>[({equipment:'Vybavení',wages:'Baristé',manager:'Vedoucí',rent:'Nájem',ingredients:'Suroviny',overhead:'Provoz',marketing:'Marketing',coffee:'Káva'})[k]||k,money(v)]))}<h3>Rozhodnutí vedení</h3><p>${s.last.decisions.map(esc).join('<br>')||'Bez automatické změny.'}</p>`;}
 if(reportKind5==='people'){const plans=state.empire.planHistory.filter(p=>p.pid===id&&p.status==='reviewed');extra=`<h3>Vyhodnocené závazky</h3><p>${plans.length?plans.filter(p=>p.success).length+' z '+plans.length+' plánů splnilo cíl.':'Zatím žádný vyhodnocený plán.'}</p>`;}
 show(`<span class="eyelabel">REPORT · ${report.count} ZAZNAMENANÝCH TÝDNŮ</span><h2>${esc(r.name)}</h2><p class="sub">${esc(r.points.at(-1)?.scope||r.scope)} · ${esc(r.owner)}${r.historical?' · historický záznam, původní role už není aktuální':''}</p>${rows(Object.entries(fields).map(([key,cfg])=>[cfg[0],reportValue5(r.values[key],cfg)]))}<p class="${r.severity===2?'bad':''}">${esc(r.issue)}</p><h3>Týdenní vývoj · ${fields[REPORT_GROUPS5[reportKind5].primary][0]}</h3>${r.points.length?`<div class="table-scroll"><table class="data"><thead><tr><th>Týden</th><th>Výsledek</th><th>Odpovědnost</th></tr></thead><tbody>${r.points.map(p=>`<tr><td>${p.week}</td><td>${reportValue5(p.values[REPORT_GROUPS5[reportKind5].primary],fields[REPORT_GROUPS5[reportKind5].primary])}</td><td>${esc(p.owner)}</td></tr>`).join('')}</tbody></table></div>`:'<p>Pro toto období ještě není zaznamenaný výsledek.</p>'}${extra}<button class="primary" id="reportManage5">Přejít na řízení</button>${reportKind5==='stores'?'<button class="soft" id="reportDay5">Otevřít průběh dne</button>':''}`);
 el('reportManage5').onclick=()=>{el('modal').close();if(reportKind5==='stores')filterCity=loc(id).city;goto(dest)};if(el('reportDay5'))el('reportDay5').onclick=()=>{el('modal').close();liveStore=id;goto('live')};
}
bind=function(){REPORT_UI5.bind();if(el('openPerformance5'))el('openPerformance5').onclick=()=>goto('performance');on('[data-report-kind]',b=>{reportKind5=b.dataset.reportKind;render()});if(el('reportWeeks5'))el('reportWeeks5').onchange=()=>{reportWeeks5=Number(el('reportWeeks5').value);render()};if(el('reportSort5'))el('reportSort5').onchange=()=>{reportSort5=el('reportSort5').value;render()};on('[data-performance-detail]',b=>performanceDetail5(b.dataset.performanceDetail));};
help=function(){REPORT_UI5.help();const p=document.createElement('p');p.textContent='Report firmy otevřeš v horní liště nebo v navigaci. Zvol poslední týden, čtyři týdny nebo čtvrtletí a typ provozu. Detail ukazuje náklady, odpovědnost a týdenní vývoj; z něj přejdeš na řízení. Nově se uchovává 26 týdnů podrobných výsledků. Starší uložená hra má nejprve dostupný jen poslední týden.';el('modalContent').append(p)};el('help').onclick=help;
render();
